import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { LocalStorageService } from '../../services/localStorage/local-storage.service';

@Component({
  selector: 'app-welcome',
  imports: [CommonModule],
  templateUrl: './welcome.component.html',
  styleUrl: './welcome.component.css'
})
export class WelcomeComponent implements OnInit {
  userName = '';
  userType = '';
  welcomeMessage = '';
  private localStorageService = inject(LocalStorageService);
  private router = inject(Router);

  ngOnInit() {
    this.loadUserData();
  }

  private loadUserData() {
    const userData = this.localStorageService.getUser();

    if (userData && userData.user) {
      this.userName = userData.user.name || 'Usuario';
      this.userType = userData.user.user_type;
      this.setWelcomeMessage();
    } else {
      this.userName = 'Invitado';
      this.userType = 'EXTERNO';
      this.welcomeMessage = 'Bienvenido al Sistema';
    }
  }

  private setWelcomeMessage() {
    const greetings = [
      '¡Hola', '¡Bienvenido/a', '¡Qué bueno verte', '¡Saludos'
    ];
    const randomGreeting = greetings[Math.floor(Math.random() * greetings.length)];

    this.welcomeMessage = `${randomGreeting}, ${this.userName}!`;
  }

  isInternalUser(): boolean {
    return this.userType === 'INTERNO';
  }

  isExternalUser(): boolean {
    return this.userType === 'EXTERNO';
  }

  navigateToDatosUsuario() {
    // Verificar si el usuario tiene datos_iniciales registrados
    const userData = this.localStorageService.getUser();
    if (userData?.user?.datos_iniciales === null) {
      // Redirigir al formulario de registro si no está registrado
      this.router.navigate(['/main/externos/datos-usuario']);
    } else {
      // Navegar a la vista de datos registrados
      this.router.navigate(['/main/externos/datos-iniciales-registrados']);
    }
  }

  navigateToPropuestas() {
    // Verificar si el usuario tiene datos_iniciales registrados
    const userData = this.localStorageService.getUser();
    if (userData?.user?.datos_iniciales === null) {
      // Redirigir a datos-usuario si no está registrado
      this.router.navigate(['/main/externos/datos-usuario']);
    } else {
      // Navegar al listado de propuestas
      this.router.navigate(['/main/externos/propuesta-list']);
    }
  }

  /**
   * Navega al perfil del usuario
   */
  navigateToProfile(): void {
    this.router.navigate(['/main/usuarios/editar']);
  }

  /**
   * Navega a propuestas registradas (internos)
   */
  navigateToPropuestasRegistradas(): void {
    this.router.navigate(['/main/internos/propuestas-registradas']);
  }

  /**
   * Navega a la sección de reportes
   */
  navigateToReportes(): void {
    this.router.navigate(['/main/internos/reportes']);
  }

  hasRegisteredInitialData(): boolean {
    const userData = this.localStorageService.getUser();
    return userData?.user?.datos_iniciales !== null;
  }
}